def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    pressure_bids = []
    urgent_opps = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                weighted = float(bid)
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                    weighted += 8.0
                    urgent_opps += 1
                if opp.get('budget', 0) < float(bid):
                    weighted = max(weighted * 0.75, 0.0)
                pressure_bids.append(weighted)

    if not alive:
        return float(min(budget, 18.0))

    competitors = len(alive) + 1
    expected_units = float(supply) / float(WATER_REQ)
    tightness = competitors - expected_units

    strongest_prev = max(prev_bids) if prev_bids else 0.0
    strongest_pressure = max(pressure_bids) if pressure_bids else 0.0

    if hp <= 2 or no_water >= 2:
        emergency = max(62.0, strongest_prev + 3.0, strongest_pressure)
        return float(min(budget, emergency))

    if hp <= 4 or no_water >= 1:
        if tightness > 2.0:
            bid = max(52.0, strongest_prev + 2.0, strongest_pressure)
        else:
            bid = max(42.0, min(58.0, strongest_prev + 1.0))
        return float(min(budget, bid))

    if supply >= 23:
        base = 16.0
    elif supply >= 20:
        base = 24.0
    elif supply >= 18:
        base = 34.0
    else:
        base = 44.0

    if tightness > 2.5:
        base += 12.0
    elif tightness > 1.5:
        base += 7.0
    elif tightness < 0.5:
        base -= 6.0

    if strongest_prev >= 110.0:
        base = min(base, 28.0)
    elif strongest_prev >= 80.0:
        base = min(max(base, 26.0), 40.0)
    elif strongest_prev > 0.0:
        target = strongest_prev + 1.5
        if target <= 55.0:
            base = max(base, target)

    if urgent_opps >= 2 and supply <= 17:
        base += 8.0

    if budget < 120.0:
        base = min(base, 0.42 * budget)
    elif budget < 220.0:
        base = min(base, 0.33 * budget)

    base = max(8.0, min(base, 63.0))
    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    budget = my_status['budget']
    hp = my_status['hp']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Extract yesterday's bids from previous_trace
    yesterday_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            yesterday_bids.append(trace['bid'])

    # Determine target bid
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        # If we need water urgently
        if hp <= 2:
            target_bid = min(budget, max(DAILY_SALARY * 0.9, max_prev_bid + 1.0))
        else:
            # If previous max bid is very high, we may need to match or exceed
            if max_prev_bid >= DAILY_SALARY * 0.8:
                if hp > 4:
                    # We can afford to be slightly lower
                    target_bid = min(budget, max(DAILY_SALARY * 0.5, max_prev_bid - 5.0))
                else:
                    # Need water, bid above
                    target_bid = min(budget, max_prev_bid + 1.0)
            else:
                # Moderate competition
                target_bid = min(budget, max(DAILY_SALARY * 0.5, max_prev_bid + 1.5))
    else:
        # First day or no previous data: base on HP
        if hp <= 2:
            target_bid = min(budget, DAILY_SALARY * 0.85)
        else:
            target_bid = min(budget, DAILY_SALARY * 0.6)

    # Ensure bid is non-negative and within budget
    bid = max(0.0, min(budget, target_bid))
    return bid
